def touches(g, cells, col, radius=1):
    # do any cells within radius of the match region have color col?
    S=set(cells)
    for (r,c) in cells:
        for dr in range(-radius,radius+1):
            for dc in range(-radius,radius+1):
                rr,cc=r+dr,c+dc
                if 0<=rr<len(g) and 0<=cc<len(g[0]) and (rr,cc) not in S and g[rr][cc]==col:
                    return True
    return False

